//SHAPES

export const shapes: Record<
    string,
    (x: number, y: number, r: number, ctx: CanvasRenderingContext2D) => void
> = {
    circle: (x, y, r, ctx) => {
        ctx.beginPath();
        ctx.arc(x, y, r, 0, 2 * Math.PI);
        ctx.fill();
    },
    rectangle: (x, y, r, ctx) =>
        ctx.fillRect(x - r, y - r * 0.66, r * 2, r * 1.33),
    triangle: (x, y, r, ctx) => {
        ctx.beginPath();
        ctx.moveTo(x, y - r);
        ctx.lineTo(x - r, y + r);
        ctx.lineTo(x + r, y + r);
        ctx.fill();
    },
    rhombus: (x, y, r, ctx) => {
        ctx.beginPath();
        ctx.moveTo(x, y - r);
        ctx.lineTo(x + r, y);
        ctx.lineTo(x, y + r);
        ctx.lineTo(x - r, y);
        ctx.closePath();
        ctx.fill();
    },
    diamond: (x, y, r, ctx) => {
        ctx.beginPath();
        ctx.moveTo(x, y - r);
        ctx.lineTo(x + r, y);
        ctx.lineTo(x, y + r);
        ctx.lineTo(x - r, y);
        ctx.closePath();
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = ctx.fillStyle as string;
        ctx.stroke();
    },
    halfcircle: (x, y, r, ctx) => {
        ctx.beginPath();
        ctx.arc(x, y, r, Math.PI / 2, 1.5 * Math.PI);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(x, y, r, -Math.PI / 2, Math.PI / 2);
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = ctx.fillStyle as string;
        ctx.stroke();
    },
    square: (x, y, r, ctx) => drawSvg(hybridIcon, x, y, r, ctx),
    star: (x, y, r, ctx) => drawSvg(starryIcon, x, y, r, ctx),
    unknown: (x, y, r, ctx) => {
        ctx.font = `${r * 2}px Sans-Serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("?", x, y);
    },
};

export const SHAPE_NAMES = Object.keys(shapes);
